namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.app.services;
using ghidra.program.model.data;
using ghidra.service.graph;
using ghidra.util;
using ghidra.util;
using ghidra.util.task;

/*
 * Action to display a Composite data type as a graph from the Data Type Manager
 *
 * The graphing is done recursively in a separate task
 */
public class DisplayTypeAsGraphAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	/*
	 * Constructor
	 *
	 * @param plugin the plugin this action is contained in
	 */
	public DisplayTypeAsGraphAction(DataTypeManagerPlugin plugin) : base("Display Data Type as Graph", plugin.getName())
    {
		this.plugin = plugin;

		string menuGroup = "ZVeryLast"; // it's own group; on the bottom
		setPopupMenuData(new MenuData(new string[] { "Display as Graph" }, null, menuGroup));
		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Type_Graph"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GraphDisplayBroker broker = plugin.getTool().getService(typeof(GraphDisplayBroker));
		if (broker == null) {
			Msg.showError(this, null, "Missing Plugin", "The Graph plugin is not installed.\n" +
				"Please add the plugin implementing this service.");
			return;
		}
		GraphDisplayProvider service = broker.getDefaultGraphDisplayProvider();

		GTree gTree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gTree.getSelectionPaths();

		foreach (TreePath path in selectionPaths) {
			GTreeNode node = (GTreeNode) path.getLastPathComponent();
			if (!(node is DataTypeNode)) {
				continue;
			}
			DataTypeNode dataTypeNode = (DataTypeNode) node;
			DataType dt = dataTypeNode.getDataType();
			if (dt is TypeDef) {
				dt = ((TypeDef) dt).getBaseDataType();
			}
			if (dt is Composite || dt is Pointer) {
				TypeGraphTask task = new TypeGraphTask(dataTypeNode.getDataType(), service);
				new TaskLauncher(task, plugin.getTool().getToolFrame());
			}
		}

	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		bool enabled = false;

		if (!(context is DataTypesActionContext)) {
			return enabled;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();

		foreach (TreePath path in selectionPaths) {

			GTreeNode node = (GTreeNode) path.getLastPathComponent();
			if (!(node is DataTypeNode)) {
				continue;
			}

			DataTypeNode dtNode = (DataTypeNode) node;
			DataType dt = dtNode.getDataType();
			if (dt is TypeDef) {
				dt = ((TypeDef) dt).getBaseDataType();
			}
			if (dt is Composite || dt is Pointer) {
				enabled = true;
			}
		}
		return enabled;
	}

}
